def compute(vars):
    net_income_effect = vars["v1"]
    other_comprehensive_income_effect = vars["v2"]
    total_effect = net_income_effect + other_comprehensive_income_effect

    return {
        "value": total_effect,
        "trace": {
            "net_income_effect": net_income_effect,
            "other_comprehensive_income_effect": other_comprehensive_income_effect,
            "total_effect": total_effect,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": None,
            },
        },
    }
